	t.Parallel()
	f := Filter{Match: "/home/user/project", Replace: "__ent__/repo"}
	got := f.Clean([]byte("file at /home/user/project/src/main.go"))
	want := "file at __ent__/repo/src/main.go"
	if string(got) != want {
		t.Errorf("Clean() = %q, want %q", got, want)
