	}
	input := []byte("repo=__ent__/repo home=__ent__/home")
	got := string(p.Smudge(input))
	want := "repo=/home/user/project home=/home/user"
	if got != want {
		t.Errorf("Smudge() = %q, want %q", got, want)
	}
}

