  1→// Package filter provides clean/smudge transcript filtering for path normalization.
  2→// Transcripts stored in checkpoints contain absolute paths (repo root, home directory)
  3→// which are machine-specific. This package normalizes paths on store (clean) and
  4→// restores them on read (smudge), similar to git's clean/smudge filter pipeline.
  5→package filter
  6→
  7→import "bytes"
  8→
  9→// Filter defines a single find-and-replace pair used during clean/smudge.
 10→// Clean replaces Match with Replace; Smudge reverses the substitution.
 11→type Filter struct {
 12→	Match   string // literal string to find
 13→	Replace string // literal string to substitute
 14→}
 15→
 16→// Clean applies the filter in the "store" direction: Match → Replace.
 17→func (f Filter) Clean(data []byte) []byte {
 18→	return bytes.ReplaceAll(data, []byte(f.Match), []byte(f.Replace))
 19→}
 20→
 21→// Smudge applies the filter in the "restore" direction: Replace → Match.
 22→func (f Filter) Smudge(data []byte) []byte {
 23→	return bytes.ReplaceAll(data, []byte(f.Replace), []byte(f.Match))
 24→}
 25→
 26→// Pipeline holds an ordered list of filters and applies them collectively.
 27→type Pipeline struct {
 28→	filters []Filter
 29→}
 30→
 31→// NewPipeline creates a filter pipeline with built-in path filters and optional user filters.
 32→// Built-in filters (applied first, most-specific first):
 33→//  1. repoRoot → __ent__/repo
 34→//  2. homeDir  → __ent__/home
 35→//
 36→// User filters are appended after built-ins.
 37→func NewPipeline(repoRoot, homeDir string, userFilters []UserFilter) (*Pipeline, error) {
 38→	var filters []Filter
 39→
 40→	// Built-in filters, most-specific first (repo root before home dir,
 41→	// since repo root is typically under home dir).
 42→	if repoRoot != "" {
 43→		f := Filter{Match: repoRoot, Replace: "__ent__/repo"}
 44→		if err := ValidateFilter(f, true); err != nil {
 45→			return nil, err
 46→		}
 47→		filters = append(filters, f)
 48→	}
 49→	if homeDir != "" {
 50→		f := Filter{Match: homeDir, Replace: "__ent__/home"}
 51→		if err := ValidateFilter(f, true); err != nil {
 52→			return nil, err
 53→		}
 54→		filters = append(filters, f)
 55→	}
 56→
 57→	// User filters
 58→	for _, uf := range userFilters {
 59→		f := Filter{
 60→			Match:   uf.Match,
 61→			Replace: "__ent_user__/" + uf.Key,
 62→		}
 63→		if err := ValidateFilter(f, false); err != nil {
 64→			return nil, err
 65→		}
 66→		filters = append(filters, f)
 67→	}
 68→
 69→	return &Pipeline{filters: filters}, nil
 70→}
 71→
 72→// UserFilter is the user-facing configuration for a custom transcript filter.
 73→type UserFilter struct {
 74→	Match string // literal string to find
 75→	Key   string // becomes __ent_user__/<key> as the replacement
 76→}
 77→
 78→// Clean applies all filters in order (store direction).
 79→func (p *Pipeline) Clean(data []byte) []byte {
 80→	for _, f := range p.filters {
 81→		data = f.Clean(data)
 82→	}
 83→	return data
 84→}
 85→
 86→// Smudge applies all filters in reverse order (restore direction).
 87→func (p *Pipeline) Smudge(data []byte) []byte {
 88→	for i := len(p.filters) - 1; i >= 0; i-- {
 89→		data = p.filters[i].Smudge(data)
 90→	}
 91→	return data
 92→}
 93→
 94→// CleanString applies Clean to a string value.
 95→func (p *Pipeline) CleanString(s string) string {
 96→	return string(p.Clean([]byte(s)))
 97→}
 98→
 99→// SmudgeString applies Smudge to a string value.
100→func (p *Pipeline) SmudgeString(s string) string {
101→	return string(p.Smudge([]byte(s)))
102→}
103→

  1→// Package settings provides configuration loading for Entire.
  2→// This package is separate from cli to allow strategy package to import it
  3→// without creating an import cycle (cli imports strategy).
  4→package settings
  5→
  6→import (
  7→	"bytes"
  8→	"context"
  9→	"encoding/json"
 10→	"fmt"
 11→	"os"
 12→	"path/filepath"
 13→	"strings"
 14→
 15→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→const (
 20→	// EntireSettingsFile is the path to the Entire settings file
 21→	EntireSettingsFile = ".entire/settings.json"
 22→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
 23→	EntireSettingsLocalFile = ".entire/settings.local.json"
 24→)
 25→
 26→// Commit linking mode constants.
 27→const (
 28→	// CommitLinkingAlways auto-links commits to sessions without prompting.
 29→	CommitLinkingAlways = "always"
 30→	// CommitLinkingPrompt prompts the user on each commit (default for existing users).
 31→	CommitLinkingPrompt = "prompt"
 32→)
 33→
 34→// EntireSettings represents the .entire/settings.json configuration
 35→type EntireSettings struct {
 36→
 37→	// Enabled indicates whether Entire is active. When false, CLI commands
 38→	// show a disabled message and hooks exit silently. Defaults to true.
 39→	Enabled bool `json:"enabled"`
 40→
 41→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
 42→	// This is used for development when the binary is not installed
 43→	LocalDev bool `json:"local_dev,omitempty"`
 44→
 45→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 46→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 47→	// Defaults to "info".
 48→	LogLevel string `json:"log_level,omitempty"`
 49→
 50→	// StrategyOptions contains strategy-specific configuration
 51→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 52→
 53→	// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
 54→	// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
 55→	// that don't source shell profiles and can't find "entire" on PATH.
 56→	AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
 57→
 58→	// Telemetry controls anonymous usage analytics.
 59→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 60→	Telemetry *bool `json:"telemetry,omitempty"`
 61→
 62→	// Redaction configures PII redaction behavior for transcripts and metadata.
 63→	Redaction *RedactionSettings `json:"redaction,omitempty"`
 64→
 65→	// CommitLinking controls how commits are linked to agent sessions.
 66→	// "always" = auto-link without prompting, "prompt" = ask on each commit.
 67→	// Defaults to "prompt" (preserves existing user behavior).
 68→	CommitLinking string `json:"commit_linking,omitempty"`
 69→
 70→	// ExternalAgents enables discovery and registration of external agent
 71→	// plugins (entire-agent-* binaries on $PATH). Defaults to false.
 72→	ExternalAgents bool `json:"external_agents,omitempty"`
 73→
 74→	// TranscriptFilters defines user-supplied clean/smudge filters applied to
 75→	// transcripts before storage. Each entry's Match is replaced by
 76→	// __ent_user__/<Key> on clean; the substitution is reversed on smudge.
 77→	TranscriptFilters []TranscriptFilter `json:"transcript_filters,omitempty"`
 78→
 79→	// Deprecated: no longer used. Exists to tolerate old settings files
 80→	// that still contain "strategy": "auto-commit" or similar.
 81→	Strategy string `json:"strategy,omitempty"`
 82→}
 83→
 84→// TranscriptFilter is a user-configured find-and-replace pair for transcripts.
 85→// Match is the literal string to find; Key becomes __ent_user__/<Key> as the replacement.
 86→type TranscriptFilter struct {
 87→	Match string `json:"match"`
 88→	Key   string `json:"key"`
 89→}
 90→
 91→// RedactionSettings configures redaction behavior beyond the default secret detection.
 92→type RedactionSettings struct {
 93→	PII *PIISettings `json:"pii,omitempty"`
 94→}
 95→
 96→// PIISettings configures PII detection categories.
 97→// When Enabled is true, email and phone default to true; address defaults to false.
 98→type PIISettings struct {
 99→	Enabled        bool              `json:"enabled"`
100→	Email          *bool             `json:"email,omitempty"`
101→	Phone          *bool             `json:"phone,omitempty"`
102→	Address        *bool             `json:"address,omitempty"`
103→	CustomPatterns map[string]string `json:"custom_patterns,omitempty"`
104→}
105→
106→// GetCommitLinking returns the effective commit linking mode.
107→// Returns the explicit value if set, otherwise defaults to "prompt"
108→// to preserve existing user behavior.
109→func (s *EntireSettings) GetCommitLinking() string {
110→	if s.CommitLinking != "" {
111→		return s.CommitLinking
112→	}
113→	return CommitLinkingPrompt
114→}
115→
116→// Load loads the Entire settings from .entire/settings.json,
117→// then applies any overrides from .entire/settings.local.json if it exists.
118→// Returns default settings if neither file exists.
119→// Works correctly from any subdirectory within the repository.
120→func Load(ctx context.Context) (*EntireSettings, error) {
121→	// Get absolute paths for settings files
122→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
123→	if err != nil {
124→		settingsFileAbs = EntireSettingsFile // Fallback to relative
125→	}
126→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
127→	if err != nil {
128→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
129→	}
130→
131→	// Load base settings
132→	settings, err := loadFromFile(settingsFileAbs)
133→	if err != nil {
134→		return nil, fmt.Errorf("reading settings file: %w", err)
135→	}
136→
137→	// Apply local overrides if they exist
138→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
139→	if err != nil {
140→		if !os.IsNotExist(err) {
141→			return nil, fmt.Errorf("reading local settings file: %w", err)
142→		}
143→		// Local file doesn't exist, continue without overrides
144→	} else {
145→		if err := mergeJSON(settings, localData); err != nil {
146→			return nil, fmt.Errorf("merging local settings: %w", err)
147→		}
148→	}
149→
150→	return settings, nil
151→}
152→
153→// LoadFromFile loads settings from a specific file path without merging local overrides.
154→// Returns default settings if the file doesn't exist.
155→// Use this when you need to display individual settings files separately.
156→func LoadFromFile(filePath string) (*EntireSettings, error) {
157→	return loadFromFile(filePath)
158→}
159→
160→// loadFromFile loads settings from a specific file path.
161→// Returns default settings if the file doesn't exist.
162→func loadFromFile(filePath string) (*EntireSettings, error) {
163→	settings := &EntireSettings{
164→		Enabled: true, // Default to enabled
165→	}
166→
167→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
168→	if err != nil {
169→		if os.IsNotExist(err) {
170→			return settings, nil
171→		}
172→		return nil, fmt.Errorf("%w", err)
173→	}
174→
175→	dec := json.NewDecoder(bytes.NewReader(data))
176→	dec.DisallowUnknownFields()
177→	if err := dec.Decode(settings); err != nil {
178→		return nil, fmt.Errorf("parsing settings file: %w", err)
179→	}
180→
181→	// Validate commit_linking if set
182→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
183→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
184→	}
185→
186→	return settings, nil
187→}
188→
189→// mergeJSON merges JSON data into existing settings.
190→// Only non-zero values from the JSON override existing settings.
191→func mergeJSON(settings *EntireSettings, data []byte) error {
192→	// First, validate that there are no unknown keys using strict decoding
193→	dec := json.NewDecoder(bytes.NewReader(data))
194→	dec.DisallowUnknownFields()
195→	var temp EntireSettings
196→	if err := dec.Decode(&temp); err != nil {
197→		return fmt.Errorf("parsing JSON: %w", err)
198→	}
199→
200→	// Parse into a map to check which fields are present
201→	var raw map[string]json.RawMessage
202→	if err := json.Unmarshal(data, &raw); err != nil {
203→		return fmt.Errorf("parsing JSON: %w", err)
204→	}
205→
206→	// Override enabled if present
207→	if enabledRaw, ok := raw["enabled"]; ok {
208→		var e bool
209→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
210→			return fmt.Errorf("parsing enabled field: %w", err)
211→		}
212→		settings.Enabled = e
213→	}
214→
215→	// Override local_dev if present
216→	if localDevRaw, ok := raw["local_dev"]; ok {
217→		var ld bool
218→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
219→			return fmt.Errorf("parsing local_dev field: %w", err)
220→		}
221→		settings.LocalDev = ld
222→	}
223→
224→	// Override absolute_git_hook_path if present
225→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
226→		var ahp bool
227→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
228→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
229→		}
230→		settings.AbsoluteGitHookPath = ahp
231→	}
232→
233→	// Override log_level if present and non-empty
234→	if logLevelRaw, ok := raw["log_level"]; ok {
235→		var ll string
236→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
237→			return fmt.Errorf("parsing log_level field: %w", err)
238→		}
239→		if ll != "" {
240→			settings.LogLevel = ll
241→		}
242→	}
243→
244→	// Merge strategy_options if present
245→	if optionsRaw, ok := raw["strategy_options"]; ok {
246→		var opts map[string]any
247→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
248→			return fmt.Errorf("parsing strategy_options field: %w", err)
249→		}
250→		if settings.StrategyOptions == nil {
251→			settings.StrategyOptions = opts
252→		} else {
253→			for k, v := range opts {
254→				settings.StrategyOptions[k] = v
255→			}
256→		}
257→	}
258→
259→	// Override telemetry if present
260→	if telemetryRaw, ok := raw["telemetry"]; ok {
261→		var t bool
262→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
263→			return fmt.Errorf("parsing telemetry field: %w", err)
264→		}
265→		settings.Telemetry = &t
266→	}
267→
268→	// Merge redaction sub-fields if present (field-level, not wholesale replace).
269→	if redactionRaw, ok := raw["redaction"]; ok {
270→		if settings.Redaction == nil {
271→			settings.Redaction = &RedactionSettings{}
272→		}
273→		if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
274→			return fmt.Errorf("parsing redaction field: %w", err)
275→		}
276→	}
277→
